/* Reviewed Term 03 source additions ported from the stale lexical-links PR.
   Only unique source headwords from FA3/KH3/N3/SH3 are included here.
   42 overlapping/repeated headword rows remain in a manual reconciliation queue. */
(()=>{
 const rows=[];
 const N=(unit,source,fa,tr,en,...args)=>{
  const hasPos=/^(?:اسم|صفت|گروه|عبارت|عنوان|قید|ساخت|اصطلاح|فعل)[^—–-]{0,35}[—–-]/.test(args[0]||"");
  const pos=hasPos?args[0]:"اسم — ism (noun)";
  const exFa=args[hasPos?1:0],exTr=args[hasPos?2:1],exEn=args[hasPos?3:2],note=args[hasPos?4:3]||"";
  rows.push({unit,source,fa,tr,en,pos,ex:[exFa,exTr,exEn],...(note?{note}:{})});
 };
 const V=(unit,source,fa,tr,en,xf,xt,xe,ms,amr,mf,mt,me,af,at,ae,note="")=>rows.push({unit,source,fa,tr,en,pos:"فعل مرکب — compound verb",ms,amr,ex:[xf,xt,xe],m:[mf,mt,me],a:amr&&amr!=="—"?[af,at,ae]:null,...(note?{note}:{})});
 const A=(unit,source,fa,tr,en,exFa,exTr,exEn)=>N(unit,source,fa,tr,en,"صفت — sifat (adjective)",exFa,exTr,exEn);
 N(15,"KH3-15","سوگواری","sugvāri","mourning","سوگواری برای عزیزان طبیعی است.","Sugvāri barāye azizān tabi'i ast.","Mourning loved ones is natural.");
 V(10,"FA3-10","بوق زدن","buq zadan","to honk; to sound the horn","راننده برای هشدار دادن بوق زد.","Rānande barāye hoshdār dādan buq zad.","The driver honked to warn someone.","buq زدن","buq نزن","بوق زدن در خیابان شلوغ آلودگی صوتی ایجاد می‌کند.","Buq zadan dar khiābān-e sholugh āludegi-ye sowti ijād mikonad.","Honking on a busy street creates noise pollution.","بی‌دلیل بوق نزن.","Bi-dalil buq nazan.","Do not honk without reason.");
 N(20,"N3-10","موضوع","mozoo","topic; subject","موضوع تحقیق باید روشن و محدود باشد.","Mozoo-ye tahqiq bāyad roshan va mahdud bāshad.","A research topic should be clear and focused.");
 N(20,"N3-10","متن","matn","text","متن را پیش از تحویل دوباره بخوانید.","Matn rā pish az tahvil dobāre bekhānid.","Read the text again before submitting it.");
 N(20,"N3-10","مثال","mesāl","example","برای هر نکته یک مثال مناسب بیاورید.","Barāye har nokte yek mesāl-e monāseb biyāvarid.","Give a suitable example for each point.");
 N(20,"N3-10","جمله","jomle","sentence","هر جمله باید پیام روشنی داشته باشد.","Har jomle bāyad payām-e roshani dāshte bāshad.","Every sentence should communicate a clear message.");
 N(20,"N3-10","نوشتن","neveshtan","writing; to write","نوشتن تحقیق به برنامه‌ریزی نیاز دارد.","Neveshtan-e tahqiq be barnāme-rizi niyāz dārad.","Writing a research paper requires planning.");
 N(20,"N3-10","توجه","tavajjoh","attention","در نوشتن باید به پیوند جمله‌ها توجه کرد.","Dar neveshtan bāyad be peyvand-e jomle-hā tavajjoh kard.","When writing, attention should be paid to sentence connections.");
 N(20,"N3-10","نمره","nomre","grade; mark","استاد برای این تکلیف نمره تعیین می‌کند.","Ostād barāye in taklif nomre ta'yin mikonad.","The teacher assigns a grade for this task.");
 N(20,"N3-10","کشور","keshvar","country","دانشجویان از کشورهای گوناگون به این دانشگاه می‌آیند.","Dāneshju-yān az keshvarhā-ye gunāgun be in dāneshgāh miāyand.","Students come to this university from different countries.");
 N(20,"N3-10","اصلی","asli","main; primary","پرسش اصلی تحقیق باید دقیق باشد.","Porsesh-e asli-ye tahqiq bāyad daqiq bāshad.","The main research question should be precise.");
 N(20,"N3-10","بند","band","paragraph; section","هر بند باید یک موضوع مرکزی داشته باشد.","Har band bāyad yek mozoo-ye markazi dāshte bāshad.","Each paragraph should have one central topic.");
 N(20,"N3-10","بخش","bakhsh","section; part","تحقیق را به چند بخش مرتبط تقسیم کنید.","Tahqiq rā be chand bakhsh-e mortabet taqsim konid.","Divide the research into several related sections.");
 N(20,"N3-10","تکلیف","taklif","assignment; task","تکلیف پایانی درس را با دقت انجام دهید.","Taklif-e pāyāni-ye dars rā bā deqqat anjām dahid.","Complete the lesson's final assignment carefully.");
 N(20,"N3-10","استاد","ostād","teacher; professor","دانشجو باید برای وقت استاد احترام قائل باشد.","Dāneshju bāyad barāye vaqt-e ostād ehterām qā'el bāshad.","A student should respect the professor's time.");
 N(20,"N3-10","دانشجو","dāneshju","student; university student","دانشجو باید برای درس و پژوهش برنامه داشته باشد.","Dāneshju bāyad barāye dars va pazhuhesh barnāme dāshte bāshad.","A student should have a plan for study and research.");
 N(20,"N3-10","دانشگاه","dāneshgāh","university","دانشگاه محیطی برای یادگیری و پژوهش است.","Dāneshgāh mohiti barāye yādgiri va pazhuhesh ast.","A university is an environment for learning and research.");
 N(20,"N3-10","انتخاب","entekhāb","choice; selection","انتخاب موضوع نخستین گام تحقیق است.","Entekhāb-e mozoo nokhostin gām-e tahqiq ast.","Choosing a topic is the first step in research.");
 N(20,"N3-10","خانواده","khānevāde","family","خانواده می‌تواند از دانشجو حمایت کند.","Khānevāde mitavānad az dāneshju hemāyat konad.","A family can support a student.");
 N(20,"N3-10","کلاس","kelās","class; classroom","در کلاس با دقت به سخنان استاد گوش دهید.","Dar kelās bā deqqat be sokhanān-e ostād gush dahid.","Listen carefully to the teacher in class.");
 N(20,"N3-10","خواندن","khāndan","reading; to read","خواندن منابع معتبر کیفیت تحقیق را بهتر می‌کند.","Khāndan-e manābe'-e mo'tabar keyfiyat-e tahqiq rā behtar mikonad.","Reading reliable sources improves research quality.");
 N(20,"N3-10","توصیفی","towsifi","descriptive","پرسش توصیفی دربارهٔ ویژگی‌های یک پدیده می‌پرسد.","Porsesh-e towsifi darbāre-ye vizhegi-hā-ye yek padide miporsad.","A descriptive question asks about the features of a phenomenon.");
 N(20,"N3-10","اجتماعی","ejtemā'i","social","این مسئله پیامدهای اجتماعی نیز دارد.","In mas'ale payāmad-hā-ye ejtemā'i niz dārad.","This issue also has social consequences.");
 N(20,"N3-10","مضارع","mozāre'","present tense (grammar)","فعل مضارع برای بیان کار در زمان حال به کار می‌رود.","Fe'l-e mozāre' barāye bayān-e kār dar zamān-e hāl be kār miravad.","The present tense is used to express an action in the present.");
 N(20,"N3-10","کاربرد","kārbord","use; application","کاربرد درست واژه‌ها متن را روشن‌تر می‌کند.","Kārbord-e dorost-e vāzhehā matn rā roshan-tar mikonad.","Correct word usage makes a text clearer.");
 N(20,"N3-10","مطالب","matāleb","material; contents","مطالب را بر اساس ریزموضوع‌ها سازمان‌دهی کنید.","Matāleb rā bar asās-e riz-mozoo-hā sāzmān-dehi konid.","Organise the material according to subtopics.");
 N(20,"N3-10","جنگل","jangal","forest","حفاظت از جنگل به همکاری مردم نیاز دارد.","Hefāzat az jangal be hamkāri-ye mardom niyāz dārad.","Protecting forests requires public cooperation.");
 N(20,"N3-10","اخلاقی","akhlāqi","ethical; moral","رفتار اخلاقی اعتماد میان افراد را تقویت می‌کند.","Raftār-e akhlāqi e'temād miyān-e afrād rā taqviyat mikonad.","Ethical behaviour strengthens trust between people.");
 N(20,"N3-10","وفات","vefāt","death; passing away","پس از وفات استاد نیز می‌توان از دانش او بهره برد.","Pas az vefāt-e ostād niz mitavān az dānesh-e u bahre bord.","Even after a teacher's death, one can benefit from their knowledge.");
 N(20,"N3-10","غیاب","qeyāb","absence","در غیاب استاد نیز باید حرمت او را نگه داشت.","Dar qeyāb-e ostād niz bāyad hormat-e u rā negah dāsht.","A teacher's dignity should be respected even in their absence.");
 N(20,"N3-10","ادب","adab","courtesy; good manners","ادب در گفتار و رفتار دانشجو آشکار می‌شود.","Adab dar goftār va raftār-e dāneshju āshkār mishavad.","A student's courtesy appears in speech and behaviour.");
 N(20,"N3-10","فروتنی","forutani","humility","فروتنی مانع پرسیدن و یادگرفتن نیست.","Forutani māne'-e porsidan va yādgereftan nist.","Humility does not prevent asking questions and learning.");
 N(20,"N3-10","مطالعه","motāle'e","study; reading","مطالعهٔ پیش از کلاس فهم درس را آسان می‌کند.","Motāle'e-ye pish az kelās fahm-e dars rā āsān mikonad.","Studying before class makes the lesson easier to understand.");
 N(20,"N3-10","گفتار","goftār","speech; manner of speaking","گفتار دانشجو باید سنجیده و محترمانه باشد.","Goftār-e dāneshju bāyad sanjide va mohtaramāne bāshad.","A student's speech should be thoughtful and respectful.");
 N(20,"N3-10","مشورت","mashverat","consultation; advice","برای رفع ابهام می‌توان با استاد مشورت کرد.","Barāye raf'-e ebhām mitavān bā ostād mashverat kard.","A student can consult the teacher to resolve uncertainty.");
 N(20,"N3-10","امانت","amānat","trust; something entrusted","دانش علمی امانتی است که باید درست به کار رود.","Dānesh-e elmi amānati ast ke bāyad dorost be kār ravad.","Knowledge is a trust that should be used properly.");
 N(20,"N3-10","نظم","nazm","order; discipline","نظم در حضور و انجام تکلیف نشانهٔ مسئولیت است.","Nazm dar hozur va anjām-e taklif neshāne-ye mas'uliyat ast.","Punctuality and completing assignments show responsibility.");
 N(20,"N3-10","ریزموضوع","riz-mozoo","subtopic","هر ریزموضوع باید بخشی از پرسش اصلی را روشن کند.","Har riz-mozoo bāyad bakhshi az porsesh-e asli rā roshan konad.","Each subtopic should clarify part of the main question.");
 N(20,"N3-10","دانش","dānesh","knowledge","دانش با مطالعه و پرسش گسترش می‌یابد.","Dānesh bā motāle'e va porsesh gostareš miyābad.","Knowledge grows through study and questioning.");
 N(20,"N3-10","وقت","vaqt","time","رعایت وقت استاد نشانهٔ احترام است.","Re'āyat-e vaqt-e ostād neshāne-ye ehterām ast.","Respecting a teacher's time is a sign of respect.");
 N(20,"N3-10","اجازه","ejāze","permission","پیش از ورود به اتاق استاد اجازه بگیرید.","Pish az vorud be otāq-e ostād ejāze begirid.","Ask permission before entering the teacher's office.");
 N(20,"N3-10","پشتیبان","poshtibān","supporting; supporter","جملهٔ پشتیبان ایدهٔ اصلی بند را گسترش می‌دهد.","Jomle-ye poshtibān ide-ye asli-ye band rā gostareš midahad.","A supporting sentence develops the paragraph's main idea.");
 N(20,"N3-10","پایانی","pāyāni","final; concluding","جملهٔ پایانی بند را کامل می‌کند.","Jomle-ye pāyāni band rā kāmel mikonad.","The concluding sentence completes the paragraph.");
 N(20,"N3-10","گذشته","gozashte","past; previous","از تجربه‌های گذشته می‌توان درس گرفت.","Az tajrobehā-ye gozashte mitavān dars gereft.","One can learn from past experiences.");
 N(20,"N3-10","خانه","khāne","home; house","خانه نخستین محیط یادگیری بسیاری از کودکان است.","Khāne nokhostin mohite yādgiri-ye besyāri az kudakān ast.","Home is the first learning environment for many children.");
 N(20,"N3-10","ایران","irān","Iran","دانشجویان از شهرهای مختلف ایران به دانشگاه می‌آیند.","Dāneshju-yān az shahrhā-ye mokhtalef-e Irān be dāneshgāh miāyand.","Students come to the university from different cities in Iran.");
 N(20,"N3-10","مردم","mardom","people; the public","مردم از آموزش باکیفیت سود می‌برند.","Mardom az āmuzesh-e bākeyfiyat sud mibarand.","People benefit from high-quality education.");
 N(20,"N3-10","کار","kār","work; task","تقسیم کار به بخش‌های کوچک انجام آن را آسان می‌کند.","Taqsim-e kār be bakhshhā-ye kuchak anjām-e ān rā āsān mikonad.","Breaking work into small parts makes it easier to complete.");
 N(20,"N3-10","خوب","khub","good; well","یک متن خوب روشن و منسجم است.","Yek matn-e khub roshan va monasajem ast.","A good text is clear and coherent.");
 N(20,"N3-10","زبان","zabān","language; tongue","زبان دقیق به انتقال بهتر اندیشه کمک می‌کند.","Zabān-e daqiq be enteqāl-e behtar-e andishe komak mikonad.","Precise language helps communicate ideas.");
 N(20,"N3-10","فارسی","fārsi","Persian; Farsi","دانشجو هر روز فارسی تمرین می‌کند.","Dāneshju har ruz fārsi tamrin mikonad.","The student practises Persian every day.");
 N(20,"N3-10","اینجا","injā","here","اینجا محل مناسبی برای مطالعه است.","Injā mahall-e monāsebi barāye motāle'e ast.","This is a suitable place to study.");
 N(20,"N3-10","درس","dars","lesson; course","این درس روش سازمان‌دهی تحقیق را آموزش می‌دهد.","In dars ravesh-e sāzmān-dehi-ye tahqiq rā āmuzesh midahad.","This lesson teaches how to organise research.");
 N(20,"N3-10","کاربردی","kārbordi","practical; applicable","پیشنهاد کاربردی باید قابل اجرا باشد.","Pishnehād-e kārbordi bāyad ghābel-e ejrā bāshad.","A practical suggestion should be feasible.");
 N(20,"N3-10","موفق","movaffaq","successful","دانشجوی موفق برای یادگیری برنامه دارد.","Dāneshju-ye movaffaq barāye yādgiri barnāme dārad.","A successful student has a learning plan.");
 N(20,"N3-10","گفت‌وگو","goft-o-gu","conversation; dialogue","گفت‌وگوی محترمانه به حل اختلاف کمک می‌کند.","Goft-o-gu-ye mohtaramāne be hal-e ekhtelāf komak mikonad.","Respectful dialogue helps resolve disagreements.");
 N(20,"N3-10","گوش","gush","ear; listening","دانشجو باید هنگام درس با دقت گوش دهد.","Dāneshju bāyad hengām-e dars bā deqqat gush dahad.","A student should listen carefully during the lesson.");
 N(20,"SH3-02","هتل","hotel","hotel","مسافران در هتل اتاق رزرو کردند.","Mosāferān dar hotel otāq rezerv kardand.","The travellers booked a room at the hotel.");
 N(20,"SH3-04","رستوران","restorān","restaurant","ما برای شام به رستوران رفتیم.","Mā barāye shām be restorān raftim.","We went to a restaurant for dinner.");
 N(20,"SH3-04","غذا","ghazā","food; meal","این غذا با سبزی تازه آماده شده است.","In ghazā bā sabzi-ye tāze āmāde shode ast.","This meal was prepared with fresh vegetables.");
 N(20,"SH3-02","خرید","kharid","shopping; purchase","پیش از خرید قیمت‌ها را مقایسه کنید.","Pish az kharid gheymathā rā moghāyese konid.","Compare prices before shopping.");
 N(20,"SH3-02","پرواز","parvāz","flight","پرواز ما صبح زود حرکت می‌کند.","Parvāz-e mā sobh-e zud harekat mikonad.","Our flight departs early in the morning.");
 N(20,"SH3-01","اتاق","otāq","room","اتاق هتل تمیز و روشن بود.","Otāq-e hotel tamiz va roshan bud.","The hotel room was clean and bright.");
 N(20,"SH3-02","هواپیما","havāpeymā","airplane","هواپیما در فرودگاه فرود آمد.","Havāpeymā dar forudgāh forud āmad.","The airplane landed at the airport.");
 N(20,"SH3-03","ماشین","māshin","car; machine","ماشین را در محل مجاز پارک کنید.","Māshin rā dar mahal-e mojāz pārk konid.","Park the car in an authorised place.");
 N(20,"SH3-03","قیمت","gheymat","price","قیمت بلیت را پیش از سفر بررسی کنید.","Gheymat-e belit rā pish az safar barrasi konid.","Check the ticket price before travelling.");
 N(20,"SH3-02","تخفیف","takhfif","discount","فروشگاه برای خرید نقدی تخفیف می‌دهد.","Forushgāh barāye kharid-e naqdi takhfif midahad.","The shop gives a discount for cash purchases.");
 N(20,"SH3-02","فرودگاه","forudgāh","airport","مسافران دو ساعت زودتر به فرودگاه رسیدند.","Mosāferān do sā'at zudtar be forudgāh residand.","The passengers arrived at the airport two hours early.");
 N(20,"SH3-02","کارت","kārt","card; card key","کارت پرواز را هنگام ورود آماده کنید.","Kārt-e parvāz rā hengām-e vorud āmāde konid.","Have your boarding pass ready when entering.");
 N(20,"SH3-06","رزرو","rezerv","reservation; booking","رزرو اتاق را پیش از سفر تأیید کنید.","Rezerv-e otāq rā pish az safar ta'yid konid.","Confirm the room reservation before travelling.");
 N(20,"SH3-02","مسافر","mosāfer","passenger; traveller","مسافر باید زمان حرکت را بررسی کند.","Mosāfer bāyad zamān-e harekat rā barrasi konad.","A traveller should check the departure time.");
 N(20,"SH3-03","سرعت","sor'at","speed","راننده باید سرعت مجاز را رعایت کند.","Rānande bāyad sor'at-e mojāz rā re'āyat konad.","A driver must observe the speed limit.");
 N(20,"SH3-02","فروشگاه","forushgāh","shop; store","این فروشگاه کالاهای متنوعی دارد.","In forushgāh kālāhā-ye motanavve'i dārad.","This shop has a variety of goods.");
 N(20,"SH3-03","ستون","sotun","column; pillar","اطلاعات را در ستون درست جدول بنویسید.","Etelā'āt rā dar sotun-e dorost-e jadval benevisid.","Write the information in the correct table column.");
 N(20,"SH3-02","پول","pul","money","پیش از سفر مقداری پول همراه داشته باشید.","Pish az safar meghdāri pul hamrāh dāshte bāshid.","Carry some money before travelling.");
 N(20,"SH3-01","گفتگو","goftogu","conversation; dialogue","گفتگو میان دو دوست دربارهٔ سفر بود.","Goftogu miyān-e do dust darbāre-ye safar bud.","The conversation between two friends was about travel.");
 V(20,"N3-10","کردن","kardan","to do; to make","کردنِ کارها با نظم به دانشجو کمک می‌کند.","Kardan-e kārhā bā nazm be dāneshju komak mikonad.","Doing tasks in an orderly way helps the student.","کردن","کن","کردنِ تکلیف با دقت نشانهٔ مسئولیت است.","Kardan-e taklif bā deqqat neshāne-ye mas'uliyat ast.","Doing an assignment carefully is a sign of responsibility.","این کار را با دقت کن.","In kār rā bā deqqat kon.","Do this task carefully.");
 V(20,"N3-10","شدن","shodan","to become; to happen","بهتر شدن نتیجه به تمرین نیاز دارد.","Behtar shodan-e natije be tamrin niyāz dārad.","Improving the result requires practice.","شدن","شو","بهتر شدن با تمرین منظم ممکن است.","Behtar shodan bā tamrin-e monazzam momken ast.","Improvement is possible with regular practice.","آماده شو.","Āmāde sho.","Get ready.");
 V(20,"SH3-01","گفتن","goftan","to say; to tell","گفتنِ حقیقت اعتماد ایجاد می‌کند.","Goftan-e haqiq at e'temād ijād mikonad.","Telling the truth creates trust.","گفتن","بگو","گفتنِ سخن روشن از سوءتفاهم جلوگیری می‌کند.","Goftan-e sokhan-e roshan az su'etefāhom jelowgiri mikonad.","Speaking clearly prevents misunderstanding.","لطفاً نام خود را بگو.","Lotfan nām-e khod rā bego.","Please say your name.");
 V(20,"SH3-01","دیدن","didan","to see; to watch","دیدنِ تصویر به فهم گفت‌وگو کمک می‌کند.","Didan-e tasvir be fahm-e goft-o-gu komak mikonad.","Seeing the picture helps understand the dialogue.","دیدن","ببین","دیدنِ نشانه‌ها پیش از تصمیم‌گیری مفید است.","Didan-e neshānehā pish az tasmim-giri mofid ast.","Seeing the signs before deciding is useful.","این تصویر را ببین.","In tasvir rā bebin.","Look at this picture.");
 V(20,"SH3-02","رفتن","raftan","to go; to leave","رفتن به فرودگاه پیش از زمان پرواز بهتر است.","Raftan be forudgāh pish az zamān-e parvāz behtar ast.","It is better to go to the airport before flight time.","رفتن","برو","رفتن به موقع از نگرانی جلوگیری می‌کند.","Raftan be moghe' az negarāni jelowgiri mikonad.","Leaving on time prevents worry.","به فرودگاه برو.","Be forudgāh boro.","Go to the airport.");
 V(20,"N3-10","دانستن","dānestan","to know","دانستنِ وظایف به رفتار مسئولانه کمک می‌کند.","Dānestan-e vazāyef be raftār-e mas'ulāne komak mikonad.","Knowing one's duties helps responsible behaviour.","دانستن","بدان","دانستنِ حق دیگران برای زندگی اجتماعی لازم است.","Dānestan-e haqq-e digarān barāye zendegi-ye ejtemā'i lāzem ast.","Knowing other people's rights is necessary for social life.","این نکته را بدان.","In nokte rā bedān.","Know this point.");
 N(1,"N3-01","نویسنده","nevisande","writer; author","نویسنده باید پیش از نوشتن موضوع خود را مشخص کند.","Nevisande bāyad pish az neveshtan mozoo-ye khod rā moshakhas konad.","A writer should define the topic before writing.");
 N(1,"N3-01","کتاب","ketāb","book","این کتاب برای یادگیری زبان فارسی مفید است.","In ketāb barāye yādgiri-ye zabān-e fārsi mofid ast.","This book is useful for learning Persian.");
 N(1,"N3-01","آشنا","āshenā","familiar; acquainted","او با فرهنگ شهر آشنا شد.","U bā farhang-e shahr āshenā shod.","He became familiar with the city's culture.");
 N(1,"N3-01","شهر","shahr","city","این شهر بناهای تاریخی زیادی دارد.","In shahr banāhā-ye tārikhi-ye ziyādi dārad.","This city has many historical buildings.");
 N(1,"N3-01","نکته","nokte","point; detail","نکته‌های مهم را در دفتر یادداشت کنید.","Noktehā-ye mohem rā dar daftar yāddāsht konid.","Write the important points in your notebook.");
 N(1,"N3-01","تمرین","tamrin","exercise; practice","تمرین پایانی را در یک بند کامل بنویسید.","Tamrin-e pāyāni rā dar yek band-e kāmel benevisid.","Write the final exercise as a complete paragraph.");
 N(1,"N3-01","محتوا","mohtavā","content","محتوای نوشته باید با موضوع هماهنگ باشد.","Mohtavā-ye neveshte bā mozoo hamāhang bāshad.","The content of the writing should match its topic.");
 N(1,"N3-01","ساختار","sākhtār","structure","ساختار روشن، فهم متن را آسان می‌کند.","Sākhtār-e roshan fahm-e matn rā āsān mikonad.","A clear structure makes a text easier to understand.");
 N(1,"N3-01","دستور","dastur","instruction; grammar","در این درس دستور زبان نیز تمرین می‌شود.","Dar in dars dastur-e zabān niz tamrin mishavad.","Grammar is also practised in this lesson.");
 N(1,"N3-01","مناسب","monāseb","suitable; appropriate","برای هر مخاطب واژگان مناسب انتخاب کنید.","Barāye har mokhāteb vāzhegān-e monāseb entekhāb konid.","Choose suitable vocabulary for each audience.");
 N(1,"N3-01","کامل","kāmel","complete; whole","پاسخ کامل باید همهٔ بخش‌های پرسش را پوشش دهد.","Pāsokh-e kāmel bāyad hame-ye bakhshhā-ye porsesh rā pushesh dahad.","A complete answer should cover every part of the question.");
 N(1,"N3-01","پیدا کردن","peydā kardan","to find; to discover","پیدا کردن موضوع مناسب نخستین گام نوشتن است.","Peydā kardan-e mozoo-ye monāseb nokhostin gām-e neveshtan ast.","Finding a suitable topic is the first step in writing.");
 N(1,"N3-01","جواب","javāb","answer; reply","جواب پرسش را با جمله‌ای روشن بنویسید.","Javāb-e porsesh rā bā jomle-i roshan benevisid.","Write the answer to the question in a clear sentence.");
 N(1,"N3-01","آینده","āyande","future","برنامه‌ریزی امروز بر آینده اثر می‌گذارد.","Barnāme-rizi-ye emruz bar āyande asar migozārad.","Today's planning affects the future.");
 N(2,"N3-02","مرحله","marhale","stage; step","هر مرحلهٔ تحقیق هدف مشخصی دارد.","Har marhale-ye tahqiq hadaf-e moshakhkhasi dārad.","Each stage of research has a specific purpose.");
 N(2,"N3-02","علمی","elmi","scientific; academic","برای تحقیق علمی باید از منابع معتبر استفاده کرد.","Barāye tahqiq-e elmi bāyad az manābe'-e mo'tabar estefāde kard.","Reliable sources should be used for academic research.");
 N(2,"N3-02","انواع","anvā'","types; kinds","انواع پرسش را با مثال مقایسه کنید.","Anvā'-e porsesh rā bā mesāl moghāyese konid.","Compare the types of questions with examples.");
 N(2,"N3-02","عنوان","onvān","title; heading","عنوان تحقیق باید کوتاه و روشن باشد.","Onvān-e tahqiq bāyad kutāh va roshan bāshad.","The research title should be short and clear.");
 N(2,"N3-02","شخص","shakhs","person; individual","هر شخص می‌تواند تجربهٔ خود را بنویسد.","Har shakhs mitavānad tajrobe-ye khod rā benevisad.","Each person can write about their own experience.");
 N(2,"N3-02","ربط","rabt","connection; relevance","بین پرسش اصلی و ریزموضوع‌ها باید ربط منطقی وجود داشته باشد.","Beyn-e porsesh-e asli va riz-mozoo-hā bāyad rabt-e manteqi vojood dāshte bāshad.","There should be a logical connection between the main question and subtopics.");
 N(3,"N3-03","خوابگاه","khābgāh","dormitory; student residence","دانشجو باید مقررات خوابگاه را رعایت کند.","Dāneshju bāyad moqarrarāt-e khābgāh rā re'āyat konad.","A student should follow the dormitory rules.");
 N(3,"N3-03","مفرد","mofrad","singular (grammar)","اسم مفرد به یک شخص یا چیز اشاره می‌کند.","Esm-e mofrad be yek shakhs yā chiz eshāre mikonad.","A singular noun refers to one person or thing.");
 N(3,"N3-03","درخت","derakht","tree","درختان برای پاکیزگی هوا اهمیت دارند.","Derakhtān barāye pākizegi-ye havā ahammiyat dārand.","Trees are important for clean air.");
 N(3,"N3-03","ساده","sāde","simple; plain","جملهٔ ساده یک فعل اصلی دارد.","Jomle-ye sāde yek fe'l-e asli dārad.","A simple sentence has one main verb.");
 N(4,"N3-04","روش","ravesh","method; approach","برای حل مسئله باید روش مناسبی انتخاب کرد.","Barāye hal-e mas'ale bāyad ravesh-e monāsebi entekhāb kard.","A suitable method should be chosen to solve a problem.");
 N(4,"N3-04","عوامل","avāmel","factors; causes","عوامل گوناگون بر تصمیم انسان اثر می‌گذارند.","Avāmel-e gunāgun bar tasmim-e ensān asar migozārand.","Different factors influence a person's decisions.");
 N(5,"N3-05","اینترنت","internet","internet","استفادهٔ مسئولانه از اینترنت به آگاهی نیاز دارد.","Estefāde-ye mas'ulāne az internet be āgāhi niyāz dārad.","Responsible use of the internet requires awareness.");
 N(5,"N3-05","مجازی","majāzi","virtual; online","کلاس مجازی امکان یادگیری از راه دور را فراهم می‌کند.","Kelās-e majāzi emkān-e yādgiri az rāh-e dur rā farāham mikonad.","A virtual class makes remote learning possible.");
 N(5,"N3-05","رمضان","ramazān","Ramadan","ماه رمضان فرصتی برای عبادت و خودسازی است.","Māh-e ramazān forsati barāye ebādat va khodsāzi ast.","The month of Ramadan is an opportunity for worship and self-improvement.");
 N(5,"N3-05","جمع","jam'","plural; group; sum","در دستور زبان، جمع به بیش از یک نفر یا چیز اشاره می‌کند.","Dar dastur-e zabān jam' be bish az yek nafar yā chiz eshāre mikonad.","In grammar, the plural refers to more than one person or thing.");
 N(5,"N3-05","ویژگی","vizhegi","feature; characteristic","هر متن ویژگی‌های مخصوص به خود را دارد.","Har matn vizhegi-hā-ye makhsus be khod rā dārad.","Every text has its own features.");
 N(5,"N3-05","منظور","manzur","intention; meaning","منظور نویسنده را از متن پیدا کنید.","Manzur-e nevisande rā az matn peydā konid.","Identify the writer's intention in the text.");
 N(6,"N3-06","اینترنتی","interneti","online; internet-based","خرید اینترنتی باید از فروشگاه معتبر انجام شود.","Kharid-e interneti bāyad az forushgāh-e mo'tabar anjām shavad.","Online shopping should be done through a reliable store.");
 N(6,"N3-06","چکیده","chokide","abstract; summary","چکیده هدف و یافته‌های تحقیق را خلاصه می‌کند.","Chokide hadaf va yāftehā-ye tahqiq rā kholāse mikonad.","The abstract summarises the aim and findings of research.");
 N(6,"N3-06","داستان","dāstān","story; tale","داستان خوب شخصیت و رویدادهای روشن دارد.","Dāstān-e khub shakhsiyat va roydādhā-ye roshan dārad.","A good story has clear characters and events.");
 N(6,"N3-06","امتحان","emtehān","exam; test","برای امتحان باید از پیش برنامه‌ریزی کرد.","Barāye emtehān bāyad az pish barnāme-rizi kard.","One should plan ahead for an exam.");
 N(6,"N3-06","ثبت‌نام","sabt-nām","registration; enrolment","ثبت‌نام در کلاس پیش از آغاز ترم انجام می‌شود.","Sabt-nām dar kelās pish az āghāz-e term anjām mishavad.","Registration for the class takes place before the term begins.");
 N(6,"N3-06","مهم","mohem","important","خواب کافی برای یادگیری مهم است.","Khab-e kāfi barāye yādgiri mohem ast.","Enough sleep is important for learning.");
 N(6,"N3-06","عالی","āli","excellent","این پاسخ از نظر ساختار عالی است.","In pāsokh az nazar-e sākhtār āli ast.","This answer is excellent in structure.");
 N(6,"N3-06","زیبا","zibā","beautiful","باغ در بهار بسیار زیبا می‌شود.","Bāgh dar bahār besyār zibā mishavad.","The garden becomes very beautiful in spring.");
 N(6,"N3-06","فرزندان","farzandān","children; offspring","والدین باید به نیازهای فرزندان توجه کنند.","Vāledeyn bāyad be niyāzhā-ye farzandān tavajjoh konand.","Parents should pay attention to their children's needs.");
 N(6,"N3-06","دستورالعمل","dastur-ol'amal","instructions; guidelines","دستورالعمل را پیش از شروع کار بخوانید.","Dastur-ol'amal rā pish az shoru'-e kār bekhānid.","Read the instructions before starting the task.");
 N(1,"SH3-01","صحبت","sohbat","conversation; talk","صحبت کردن با آرامش به حل اختلاف کمک می‌کند.","Sohbat kardan bā ārāmesh be hal-e ekhtelāf komak mikonad.","Speaking calmly helps resolve disagreements.");
 N(1,"SH3-01","درست","dorost","correct; right","پاسخ درست را از میان گزینه‌ها انتخاب کنید.","Pāsokh-e dorost rā az miyān-e gozinehā entekhāb konid.","Choose the correct answer from the options.");
 N(1,"SH3-01","دوباره","dobāre","again; once more","لطفاً جمله را دوباره گوش کنید.","Lotfan jomle rā dobāre gush konid.","Please listen to the sentence again.");
 N(1,"SH3-01","نادرست","nādorost","incorrect; wrong","اطلاعات نادرست را منتشر نکنید.","Etelā'āt-e nādorost rā montasher nakonid.","Do not share incorrect information.");
 N(1,"SH3-01","مشکل","moshkel","problem; difficulty","اگر مشکلی دارید، آن را روشن توضیح دهید.","Agar moshkeli dārid, ān rā roshan tozih dahid.","If you have a problem, explain it clearly.");
 N(1,"SH3-01","فایل","fāyl","file","فایل صوتی درس را یک بار دیگر پخش کنید.","Fāyl-e sowti-ye dars rā yek bār-e digar pakhsh konid.","Play the lesson's audio file once more.");
 N(1,"SH3-01","صوتی","sowti","audio; sound-related","برای تمرین شنیداری از فایل صوتی استفاده کنید.","Barāye tamrin-e shenidāri az fāyl-e sowti estefāde konid.","Use the audio file for listening practice.");
 N(1,"SH3-01","واژه","vāzhe","word; vocabulary item","واژه‌های تازه را در دفتر بنویسید.","Vāzhehā-ye tāze rā dar daftar benevisid.","Write the new words in your notebook.");
 N(1,"SH3-01","شماره","shomāre","number; issue","شمارهٔ پرواز را روی بلیت بررسی کنید.","Shomāre-ye parvāz rā ru-ye belit barrasi konid.","Check the flight number on the ticket.");
 N(1,"SH3-01","تحصیل","tahsil","education; study","ادامهٔ تحصیل به برنامه‌ریزی نیاز دارد.","Edāme-ye tahsil be barnāme-rizi niyāz dārad.","Continuing one's education requires planning.");
 N(1,"SH3-01","نفر","nafar","person; people (counter)","سه نفر برای گفت‌وگو انتخاب شدند.","Se nafar barāye goft-o-gu entekhāb shodand.","Three people were selected for the conversation.");
 N(1,"SH3-01","محل","mahal","place; location","محل قرار را پیش از حرکت مشخص کنید.","Mahall-e gharār rā pish az harekat moshakhas konid.","Specify the meeting place before leaving.");
 N(1,"SH3-01","دست","dast","hand","پیش از غذا دست‌های خود را بشویید.","Pish az ghazā dast-hā-ye khod rā beshuyid.","Wash your hands before eating.");
 N(1,"SH3-01","خیلی","kheyli","very; a lot","این تمرین خیلی ساده نیست.","In tamrin kheyli sāde nist.","This exercise is not very easy.");
 N(1,"SH3-01","تأخیر","ta'khir","delay","پرواز به دلیل شرایط آب‌وهوا با تأخیر انجام شد.","Parvāz be dalil-e sharāyet-e āb-o-havā bā ta'khir anjām shod.","The flight was delayed because of weather conditions.");
 N(1,"SH3-01","دوره","dowre","period; course","این دوره برای تقویت گفتار طراحی شده است.","In dowre barāye taqviyat-e goftār tarāhi shode ast.","This course is designed to strengthen speaking.");
 N(2,"SH3-02","رانندگی","rānandegi","driving","رانندگی ایمن به دقت و تمرکز نیاز دارد.","Rānandegi-ye imen be deqqat va tamarkoz niyāz dārad.","Safe driving requires care and concentration.");
 N(2,"SH3-02","بلیت","belit","ticket","بلیت قطار را از پیش تهیه کردیم.","Belit-e qatār rā az pish tahye kardim.","We bought the train ticket in advance.");
 N(2,"SH3-02","حمل","haml","transport; carrying","حمل بار سنگین هزینهٔ جداگانه دارد.","Haml-e bār-e sangin hazine-ye jodāgāne dārad.","Transporting heavy luggage has an additional fee.");
 N(2,"SH3-02","تبدیل","tabdil","conversion; change","تبدیل پول را در صرافی معتبر انجام دهید.","Tabdil-e pul rā dar sarāfi-ye mo'tabar anjām dahid.","Exchange money at a reputable exchange office.");
 N(2,"SH3-02","فضا","fazā","space; atmosphere","فضای فرودگاه در ساعت‌های شلوغ پررفت‌وآمد است.","Fazā-ye forudgāh dar sā'at-hā-ye sholugh porraft-o-āmad ast.","The airport is busy during peak hours.");
 N(2,"SH3-02","تلفن","telefon","telephone; phone","شمارهٔ تلفن خود را درست وارد کنید.","Shomāre-ye telefon-e khod rā dorost vāred konid.","Enter your phone number correctly.");
 N(2,"SH3-02","مکان","makān","place; location","مکان مناسب برای توقف را انتخاب کنید.","Makān-e monāseb barāye tavaqqof rā entekhāb konid.","Choose a suitable place to stop.");
 N(3,"SH3-03","غیرمجاز","gheyr-e mojāz","unauthorised; prohibited","پارک کردن در این محل غیرمجاز است.","Pārk kardan dar in mahal gheyr-e mojāz ast.","Parking in this place is prohibited.");
 N(3,"SH3-03","مدرک","madrek","document; certificate","برای ثبت‌نام باید مدرک شناسایی ارائه دهید.","Barāye sabt-nām bāyad madrek-e shenāsāyi erā'e dahid.","You must provide identification to register.");
 N(3,"SH3-03","نقص","naqṣ","defect; fault","پیش از سفر نقص خودرو را بررسی کنید.","Pish az safar naqs-e khodro rā barrasi konid.","Check the vehicle for defects before travelling.");
 N(3,"SH3-03","رنگ","rang","colour","رنگ تابلو باید از فاصله دیده شود.","Rang-e tāblo bāyad az fāsele dide shavad.","The sign's colour should be visible from a distance.");
 N(3,"SH3-03","نوع","no'","type; kind","نوع بلیت را هنگام خرید بررسی کنید.","No'-e belit rā hengām-e kharid barrasi konid.","Check the type of ticket when buying it.");
 N(4,"SH3-04","مواد","mavādd","materials; ingredients; substances","مواد لازم برای پخت غذا را آماده کنید.","Mavādd-e lāzem barāye pokht-e ghazā rā āmāde konid.","Prepare the ingredients needed to cook the meal.");
 N(4,"SH3-04","سنتی","sonnati","traditional","این غذا با روش سنتی پخته می‌شود.","In ghazā bā ravesh-e sonnati pokhte mishavad.","This food is cooked in the traditional way.");
 N(4,"SH3-04","نمک","namak","salt","برای این غذا نمک کمتری لازم است.","Barāye in ghazā namak-e kamtari lāzem ast.","This dish needs less salt.");
 N(4,"SH3-04","پخت","pokht","cooking; preparation","پخت این غذا زمان زیادی می‌برد.","Pokht-e in ghazā zamān-e ziyādi mibarad.","Cooking this dish takes a long time.");
 N(4,"SH3-04","سفره","sofreh","tablecloth; dining spread","خانواده دور سفره جمع شدند.","Khānevāde dor-e sofreh jam' shodand.","The family gathered around the dining spread.");
 N(4,"SH3-04","گوشت","gusht","meat","برای این غذا از گوشت تازه استفاده کنید.","Barāye in ghazā az gusht-e tāze estefāde konid.","Use fresh meat for this dish.");
 N(4,"SH3-04","شیر","shir","milk; lion","کودک هر روز یک لیوان شیر می‌نوشد.","Kudak har ruz yek livān shir minushad.","The child drinks a glass of milk every day.");
 N(4,"SH3-04","غذایی","ghazāyi","food-related; culinary","مواد غذایی را در جای خنک نگهداری کنید.","Mavādd-e ghazāyi rā dar jā-ye khonak negahdāri konid.","Keep food items in a cool place.");
 N(5,"SH3-05","حذف","hazf","deletion; removal","حذف واژه‌های تکراری متن را کوتاه‌تر می‌کند.","Hazf-e vāzhehā-ye tekrāri matn rā kutāh-tar mikonad.","Removing repeated words makes the text shorter.");
 N(5,"SH3-05","عادت","ādat","habit; custom","عادت غذایی بر سلامت اثر می‌گذارد.","Ādat-e ghazāyi bar salāmat asar migozārad.","Eating habits affect health.");
 N(5,"SH3-05","اضافه","ezāfe","extra; addition","نمک اضافه به غذا نریزید.","Namak-e ezāfe be ghazā narizid.","Do not add extra salt to the food.");
 N(5,"SH3-05","کافی","kāfi","enough; sufficient","خواب کافی برای سلامت لازم است.","Khab-e kāfi barāye salāmat lāzem ast.","Enough sleep is necessary for health.");
 N(5,"SH3-05","مختلف","mokhtalef","different; various","مردم سلیقه‌های غذایی مختلفی دارند.","Mardom saliqehā-ye ghazāyi-ye mokhtalefi dārand.","People have different food preferences.");
 N(7,"SH3-07","تماس","tamās","contact; call","برای تأیید زمان با مسئول تماس بگیرید.","Barāye ta'yid-e zamān bā mas'ul tamās begirid.","Contact the person in charge to confirm the time.");
 N(7,"SH3-07","مستمر","mostamer","continuous; ongoing","تمرین مستمر مهارت گفتاری را تقویت می‌کند.","Tamrin-e mostamer mahārat-e goftāri rā taqviyat mikonad.","Consistent practice strengthens speaking skills.");
 N(8,"SH3-08","شرکت","sherkat","company; participation","شرکت در کلاس گفت‌وگو را بهتر می‌کند.","Sherkat dar kelās goft-o-gu rā behtar mikonad.","Participating in class improves conversation.");
 N(8,"SH3-08","تحصیلی","tahsili","educational; academic","برنامهٔ تحصیلی خود را با استاد بررسی کنید.","Barnāme-ye tahsili-ye khod rā bā ostād barrasi konid.","Review your study plan with the teacher.");
 V(20,"N3-10","دادن","dādan","to give; to provide","دادنِ پاسخ دقیق به پرسش اصلی اهمیت دارد.","Dādan-e pāsokh-e daqiq be porsesh-e asli ahammiyat dārad.","Giving a precise answer to the main question is important.","دادن","بده","دادنِ فرصت پرسش به دانشجو به یادگیری کمک می‌کند.","Dādan-e forsat-e porsesh be dāneshju be yādgiri komak mikonad.","Giving students an opportunity to ask questions helps learning.","این کتاب را به دوستم بده.","In ketāb rā be dustam bede.","Give this book to my friend.");
 N(20,"N3-10","انشا","enshā","essay; composition","در انشا باید مقدمه، بدنه و نتیجهٔ روشن داشته باشیم.","Dar enshā bāyad moqaddame, badane va natije-ye roshan dāshte bāshim.","An essay should have a clear introduction, body and conclusion.");
 N(20,"N3-10","دانشمند","dāneshmand","scholar; scientist","دانشمندان اخلاق دربارهٔ احترام به استاد بحث کرده‌اند.","Dāneshmandān-e akhlāq darbāre-ye ehterām be ostād bahs karde-and.","Ethicists have discussed respect for teachers.");
 N(20,"N3-10","قالب","qāleb","form; format; framework","این نوشته در قالب چهار بخش تنظیم شده است.","In neveshte dar qāleb-e chahār bakhsh tanzim shode ast.","This writing is arranged in a four-part format.");
 N(20,"N3-10","بدنه","badane","body (of an essay or text)","بدنهٔ انشا شامل بندهای اصلی است.","Badane-ye enshā shāmel-e bandhā-ye asli ast.","The body of an essay contains its main paragraphs.");
 N(20,"N3-10","جایگاه","jāygāh","position; status; place","جایگاه استاد در فرایند آموزش مهم است.","Jāygāh-e ostād dar farāyand-e āmuzesh mohem ast.","The teacher's role in the educational process is important.");
 N(20,"N3-10","بیرون","birun","outside; outdoors","دانشجو بیرون از کلاس نیز مسئولیت دارد.","Dāneshju birun az kelās niz mas'uliyat dārad.","A student also has responsibilities outside the classroom.");
 N(20,"N3-10","انتقال","enteqāl","transfer; transmission","انتقال دانش به نسل بعد ارزشمند است.","Enteqāl-e dānesh be nasl-e ba'd arzeshmand ast.","Passing knowledge to the next generation is valuable.");
 N(20,"N3-10","محدود","mahdud","limited; restricted","یادگیری به زمان کلاس محدود نیست.","Yādgiri be zamān-e kelās mahdud nist.","Learning is not limited to class time.");
 N(20,"N3-10","رابطه","rābete","relationship; connection","رابطهٔ استاد و دانشجو باید بر احترام استوار باشد.","Rābete-ye ostād va dāneshju bāyad bar ehterām ostovār bāshad.","The teacher-student relationship should be based on respect.");
 N(20,"N3-10","شکل","shekl","form; shape","احترام به استاد شکل‌های گوناگونی دارد.","Ehterām be ostād sheklhā-ye gunāguni dārad.","Respect for a teacher takes different forms.");
 N(20,"N3-10","راهنمایی","rāhnamāyi","guidance; advice","راهنمایی استاد مسیر پژوهش را روشن می‌کند.","Rāhnamāyi-ye ostād masir-e pazhuhesh rā roshan mikonad.","A teacher's guidance clarifies the path of research.");
 N(20,"N3-10","هموار","hamvār","smooth; unobstructed","استاد مسیر یادگیری را برای دانشجو هموار می‌کند.","Ostād masir-e yādgiri rā barāye dāneshju hamvār mikonad.","A teacher makes the learning path smoother for a student.");
 N(20,"N3-10","نگاه","negāh","view; perspective","از نگاه اخلاقی، احترام با صداقت همراه است.","Az negāh-e akhlāqi, ehterām bā sedāqat hamrāh ast.","From an ethical perspective, respect goes together with honesty.");
 N(20,"N3-10","بی‌چون‌وچرا","bi-chon-o-cherā","unquestioningly; without question","دانشجو نباید هر سخنی را بی‌چون‌وچرا بپذیرد.","Dāneshju nabāyad har sokhani rā bi-chon-o-cherā bepazirad.","A student should not accept every statement unquestioningly.");
 N(20,"N3-10","دقت","deqqat","care; attention; precision","گوش دادن با دقت به فهم درس کمک می‌کند.","Gush dādan bā deqqat be fahm-e dars komak mikonad.","Listening attentively helps understanding the lesson.");
 N(20,"N3-10","به‌موقع","be-moghe'","on time; at the right time","دانشجو باید به‌موقع در کلاس حاضر شود.","Dāneshju bāyad be-moghe' dar kelās hāzer shavad.","A student should arrive in class on time.");
 N(20,"N3-10","حاضر","hāzer","present; ready","همهٔ دانشجویان در کلاس حاضر بودند.","Hame-ye dāneshju-yān dar kelās hāzer budand.","All the students were present in class.");
 N(20,"N3-10","آمادگی","āmādegi","preparation; readiness","آمادگی پیش از کلاس به یادگیری بهتر کمک می‌کند.","Āmādegi-ye pish az kelās be yādgiri-ye behtar komak mikonad.","Preparation before class helps learning.");
 N(20,"N3-10","مطلب","matlab","matter; point; content","اگر مطلبی روشن نیست، آن را محترمانه بپرسید.","Agar matlab-i roshan nist, ān rā mohtaramāne beporsid.","If a point is unclear, ask about it politely.");
 N(20,"N3-10","جدیت","jeddiat","seriousness; diligence","جدیت در مطالعه نشانهٔ مسئولیت‌پذیری است.","Jeddiat dar motāle'e neshāne-ye mas'uliyat-paziri ast.","Seriousness in study is a sign of responsibility.");
 N(20,"N3-10","ملاقات","molāqāt","meeting; visit","برای ملاقات با استاد زمان مناسبی درخواست کنید.","Barāye molāqāt bā ostād zamān-e monāsebi darkhāst konid.","Request a suitable time to meet the teacher.");
 N(20,"N3-10","نسبت","nesbat","attribution; relation","نسبت دادن سخن نادرست به دیگران اخلاقی نیست.","Nesbat dādan-e sokhan-e nādorost be digarān akhlāqi nist.","Attributing false statements to others is unethical.");
 N(20,"N3-10","تأییدنشده","ta'yid-nashode","unverified; unconfirmed","از انتشار خبر تأییدنشده خودداری کنید.","Az enteshār-e khabar-e ta'yid-nashode khoddāri konid.","Avoid sharing unverified news.");
 N(20,"N3-10","حرمت","hormat","dignity; respect","حفظ حرمت استاد در غیاب او نیز لازم است.","Hefz-e hormat-e ostād dar qeyāb-e u niz lāzem ast.","Respecting a teacher's dignity is necessary even in their absence.");
 N(20,"N3-10","منصفانه","monsefāne","fairly; fair-mindedly","دیدگاه استاد را منصفانه بیان کنید.","Didgāh-e ostād rā monsefāne bayān konid.","Present the teacher's viewpoint fairly.");
 N(20,"N3-10","دیدگاه","didgāh","viewpoint; perspective","اختلاف دیدگاه همیشه به معنای بی‌احترامی نیست.","Ekhtelāf-e didgāh hamishe be ma'nā-ye bi-ehterāmi nist.","A difference of viewpoint does not always mean disrespect.");
 N(20,"N3-10","اختلاف","ekhtelāf","difference; disagreement","اختلاف علمی را باید با گفت‌وگو حل کرد.","Ekhtelāf-e elmi rā bāyad bā goft-o-gu hal kard.","Academic disagreement should be resolved through discussion.");
 N(20,"N3-10","بدگویی","badguyi","speaking ill of someone; backbiting","بدگویی دربارهٔ استاد اعتماد را از بین می‌برد.","Badguyi darbāre-ye ostād e'temād rā az beyn mibarad.","Speaking ill of a teacher destroys trust.");
 N(20,"N3-10","یادکرد","yādkard","remembrance; mention","یادکرد نیک از استاد بخشی از سپاس‌گزاری است.","Yādkard-e nik az ostād bakhshi az sepās-gozāri ast.","Speaking well of a teacher is part of gratitude.");
 N(20,"N3-10","نیک","nik","good; virtuous","از استاد با نیکی یاد کنید.","Az ostād bā niki yād konid.","Remember the teacher with kindness.");
 N(20,"N3-10","آموخته","āmukhte","what has been learned","آموخته‌های استاد را به دیگران منتقل کنید.","Āmukhtehā-ye ostād rā be digarān montaqel konid.","Pass on what you have learned from the teacher.");
 N(20,"N3-10","شاگردی","shāgerdi","being a student; discipleship","شاگردی فقط حضور در کلاس نیست.","Shāgerdi faqat hozur dar kelās nist.","Being a student is not merely attending class.");
 N(20,"N3-10","تعارف","ta'ārof","polite formula; social courtesy","احترام واقعی از تعارف فراتر می‌رود.","Ehterām-e vāqe'i az ta'ārof farātar miravad.","Genuine respect goes beyond polite formulas.");
 N(20,"N3-10","کردار","kerdār","conduct; deeds","کردار دانشجو باید با گفتار او هماهنگ باشد.","Kerdār-e dāneshju bā goftār-e u hamāhang bāshad.","A student's actions should match their words.");
 N(20,"N3-10","آشکار","āshkār","clear; evident","احترام در رفتار روزانه آشکار می‌شود.","Ehterām dar raftār-e ruzāne āshkār mishavad.","Respect becomes evident in daily behaviour.");
 N(20,"N3-10","تفکر","tafakkor","thinking; reflection","تفکر مستقل با احترام به استاد منافاتی ندارد.","Tafakkor-e mostaqel bā ehterām be ostād monāfāti nadārad.","Independent thinking does not conflict with respect for a teacher.");
 N(20,"N3-10","مستقل","mostaqel","independent","دانشجو باید پرسش‌گری مستقل را تمرین کند.","Dāneshju bāyad porseshgari-ye mostaqel rā tamrin konad.","A student should practise independent inquiry.");
 N(20,"N3-10","رشد","roshd","growth; development","رابطهٔ سالم به رشد علمی و اخلاقی کمک می‌کند.","Rābete-ye sālem be roshd-e elmi va akhlāqi komak mikonad.","A healthy relationship supports academic and moral growth.");
 N(20,"N3-10","عین","eyn","same; exact; very","در عین احترام، پرسش خود را روشن مطرح کنید.","Dar eyn-e ehterām, porsesh-e khod rā roshan matrah konid.","While remaining respectful, state your question clearly.");
 N(20,"N3-10","حال","hāl","state; condition; present","در هر حال باید از انصاف پیروی کرد.","Dar har hāl bāyad az ensāf peyrovi kard.","In every circumstance, one should act fairly.");
 N(20,"N3-10","بهره","bahre","benefit; share; use","دانشجو باید از دانش استاد بهره ببرد.","Dāneshju bāyad az dānesh-e ostād bahre bebarad.","A student should benefit from the teacher's knowledge.");
 N(20,"N3-10","پاس","pās","guard; honour; preservation","پاس داشتن حرمت استاد اهمیت دارد.","Pās dāshtan-e hormat-e ostād ahammiyat dārad.","Honouring a teacher's dignity is important.");
 V(20,"N3-10","پذیرفتن","paziroftan","to accept; to acknowledge","پذیرفتنِ اشتباه نشانهٔ رشد اخلاقی است.","Paziroftan-e eshtebāh neshāne-ye roshd-e akhlāqi ast.","Accepting a mistake is a sign of moral growth.","پذیرفتن","بپذیر","پذیرفتنِ نقد سازنده به پیشرفت کمک می‌کند.","Paziroftan-e naqd-e sāzande be pishraft komak mikonad.","Accepting constructive criticism helps progress.","این پیشنهاد را بپذیر.","In pishnehād rā bepazir.","Accept this suggestion.");
 V(20,"N3-10","شنیدن","shenidan","to hear; to listen","شنیدنِ دقیق سخن استاد به یادگیری کمک می‌کند.","Shenidan-e daqiq-e sokhan-e ostād be yādgiri komak mikonad.","Listening carefully to the teacher helps learning.","شنیدن","بشنو","شنیدنِ دیدگاه مخالف به فهم بهتر مسئله کمک می‌کند.","Shenidan-e didgāh-e mokhālef be fahm-e behtar-e mas'ale komak mikonad.","Listening to an opposing viewpoint helps understand the issue.","به سخن استاد گوش کن و خوب بشنو.","Be sokhan-e ostād gush kon va khub beshno.","Listen to the teacher and hear carefully.");
 V(20,"N3-10","فهمیدن","fahmidan","to understand","فهمیدنِ مطلب به پرسش و تمرین نیاز دارد.","Fahmidan-e matlab be porsesh va tamrin niyāz dārad.","Understanding a point requires questions and practice.","فهمیدن","بفهم","فهمیدنِ دلیل یک نظر از حفظ کردن آن مهم‌تر است.","Fahmidan-e dalil-e yek nazar az hefz kardan-e ān mohem-tar ast.","Understanding the reason for a view is more important than memorising it.","این نکته را خوب بفهم.","In nokte rā khub befahm.","Understand this point well.");
 V(20,"N3-10","خواستن","khāstan","to want; to request","خواستنِ راهنمایی از استاد نشانهٔ ضعف نیست.","Khāstan-e rāhnamāyi az ostād neshāne-ye za'f nist.","Asking a teacher for guidance is not a sign of weakness.","خواستن","بخواه","خواستنِ توضیح بیشتر حق دانشجو است.","Khāstan-e tozih-e bishtar haqq-e dāneshju ast.","Asking for further explanation is a student's right.","اگر لازم است، کمک بخواه.","Agar lāzem ast, komak bekhāh.","If necessary, ask for help.");
 V(20,"N3-10","داشتن","dāshtan","to have; to possess","داشتنِ برنامه به پیشرفت دانشجو کمک می‌کند.","Dāshtan-e barnāme be pishraft-e dāneshju komak mikonad.","Having a plan helps a student progress.","داشتن","داشته باش","داشتنِ احترام به معنای کنار گذاشتن تفکر نیست.","Dāshtan-e ehterām be ma'nā-ye kenār gozāshtan-e tafakkor nist.","Having respect does not mean abandoning thought.","رفتار محترمانه داشته باش.","Raftār-e mohtaramāne dāshte bāsh.","Behave respectfully.");
 V(20,"N3-10","توانستن","tavānestan","to be able; can","توانستنِ پرسیدن پرسش درست بخشی از یادگیری است.","Tavānestan-e porsidan-e porsesh-e dorost bakhshi az yādgiri ast.","Being able to ask the right question is part of learning.","توانستن","بتوان","توانستنِ توضیح دادن نظر خود نشانهٔ فهم است.","Tavānestan-e tozih dādan-e nazar-e khod neshāne-ye fahm ast.","Being able to explain one's view is a sign of understanding.","باید بتوان پاسخ را با دلیل توضیح داد.","Bāyad betavān pāsokh rā bā dalil tozih dād.","One should be able to explain the answer with a reason.");
 N(1,"N3-01","اول","avval","first; initially","اول موضوع را انتخاب کنید و سپس طرح بنویسید.","Avval mozoo rā entekhāb konid va sepas tarh benevisid.","First choose the topic, then write an outline.");
 N(1,"N3-01","دوم","dovvom","second","در بند دوم دلیل دیگری را توضیح دهید.","Dar band-e dovvom dalil-e digari rā tozih dahid.","Explain another reason in the second paragraph.");
 N(1,"N3-01","سوم","sevvom","third","سومین نکته را در نتیجه یادآوری کنید.","Sevvomin nokte rā dar natije yādāvari konid.","Recall the third point in the conclusion.");
 N(1,"N3-01","چهارم","chahārom","fourth","چهارمین مرحله بازبینی متن است.","Chahāromin marhale bāzbini-ye matn ast.","The fourth step is reviewing the text.");
 N(1,"N3-03","صورت","surat","form; manner; face","صورت درست جمله را در جدول بنویسید.","Surat-e dorost-e jomle rā dar jadval benevisid.","Write the correct form of the sentence in the table.");
 N(1,"N3-03","فعل","fe'l","verb","فعل جمله را پیدا کنید.","Fe'l-e jomle rā peydā konid.","Find the verb in the sentence.");
 N(1,"N3-01","چند","chand","some; a few; how many","چند جمله دربارهٔ موضوع بنویسید.","Chand jomle darbāre-ye mozoo benevisid.","Write a few sentences about the topic.");
 N(1,"N3-01","تمام","tamām","all; whole; complete","تمام بخش‌های تمرین را پاسخ دهید.","Tamām-e bakhshhā-ye tamrin rā pāsokh dahid.","Answer all parts of the exercise.");
 N(1,"N3-01","نام","nām","name","نام نویسنده را زیر عنوان بنویسید.","Nām-e nevisande rā zir-e onvān benevisid.","Write the author's name below the title.");
 N(1,"N3-01","جدول","jadval","table; chart","اطلاعات را در جدول مرتب کنید.","Etelā'āt rā dar jadval morattab konid.","Organise the information in the table.");
 N(1,"N3-03","قرار","qarār","appointment; arrangement; resolution","قرار است فردا دربارهٔ تحقیق گفت‌وگو کنیم.","Qarār ast fardā darbāre-ye tahqiq goft-o-gu konim.","We are going to discuss the research tomorrow.");
 N(1,"N3-01","پیش","pish","before; ahead; in front","پیش از نوشتن، ریزموضوع‌ها را مشخص کنید.","Pish az neveshtan riz-mozoo-hā rā moshakhas konid.","Before writing, identify the subtopics.");
 N(1,"N3-01","زمان","zamān","time; period","برای هر بخش زمان کافی در نظر بگیرید.","Barāye har bakhsh zamān-e kāfi dar nazar begirid.","Allow enough time for each section.");
 N(1,"N3-01","پیدا","peydā","found; visible; available","پاسخ را در متن پیدا کنید.","Pāsokh rā dar matn peydā konid.","Find the answer in the text.");
 N(1,"N3-01","چیز","chiz","thing; something","هر چیز را با دلیل و مثال توضیح دهید.","Har chiz rā bā dalil va mesāl tozih dahid.","Explain each thing with a reason and an example.");
 N(1,"N3-01","کنار","kenār","beside; next to; alongside","در کنار موضوع اصلی، دو ریزموضوع بنویسید.","Dar kenār-e mozoo-ye asli, do riz-mozoo benevisid.","Write two subtopics alongside the main topic.");
 N(1,"N3-01","انجام","anjām","completion; performance","انجام تمرین به دقت و زمان نیاز دارد.","Anjām-e tamrin be deqqat va zamān niyāz dārad.","Completing the exercise requires care and time.");
 N(1,"N3-10","مقابل","moqābel","opposite; in front of; against","دانشجو در مقابل استاد مسئولیت اخلاقی دارد.","Dāneshju dar moqābel-e ostād mas'uliyat-e akhlāqi dārad.","A student has ethical responsibilities toward the teacher.");
 N(1,"SH3-02","کالا","kālā","goods; product","قیمت کالا را پیش از خرید بررسی کنید.","Gheymat-e kālā rā pish az kharid barrasi konid.","Check the price of the product before buying.");
 N(1,"SH3-01","پیش‌تکلیف","pish-taklif","pre-task; preparatory assignment","پیش‌تکلیف را پیش از جلسه انجام دهید.","Pish-taklif rā pish az jalase anjām dahid.","Complete the preparatory assignment before the session.");
 V(1,"N3-03","خوردن","khordan","to eat; to consume","خوردنِ غذای سالم برای بدن مفید است.","Khordan-e ghazā-ye sālem barāye badan mofid ast.","Eating healthy food is good for the body.","خوردن","بخور","خوردنِ آرام و با دقت به هضم غذا کمک می‌کند.","Khordan-e ārām va bā deqqat be hazm-e ghazā komak mikonad.","Eating slowly and carefully helps digestion.","میوهٔ تازه بخور.","Mive-ye tāze bekhor.","Eat fresh fruit.");
 V(1,"N3-03","بودن","budan","to be; to exist","بودنِ دانشجو در کلاس به‌موقع اهمیت دارد.","Budan-e dāneshju dar kelās be-moghe' ahammiyat dārad.","A student's being on time in class matters.","بودن","باش","بودن در کنار خانواده به انسان آرامش می‌دهد.","Budan dar kenār-e khānevāde be ensān ārāmesh midahad.","Being with family gives a person peace.","آماده باش.","Āmāde bāsh.","Be ready.");
 N(1,"N3-01","زیاد","ziyād","many; much; a lot","برای این موضوع مثال‌های زیادی وجود دارد.","Barāye in mozoo mesāl-hā-ye ziyādi vojood dārad.","There are many examples for this topic.");
 N(1,"N3-01","یاد","yād","memory; remembrance","یاد گرفتن واژه‌های تازه به تمرین نیاز دارد.","Yād gereftan-e vāzhehā-ye tāze be tamrin niyāz dārad.","Learning new words requires practice.");
 N(1,"N3-01","انتظار","entezār","expectation; waiting","از دانشجو انتظار می‌رود با نظم در کلاس حاضر شود.","Az dāneshju entezār miravad bā nazm dar kelās hāzer shavad.","A student is expected to attend class punctually.");
 N(1,"N3-01","بزرگ","bozorg","big; large; great","یک موضوع بزرگ را به ریزموضوع‌های کوچک تقسیم کنید.","Yek mozoo-ye bozorg rā be riz-mozoo-hā-ye kuchak taqsim konid.","Divide a large topic into smaller subtopics.");
 N(20,"N3-10","فرعی","far'i","secondary; sub-; subsidiary","پرسش فرعی به روشن شدن پرسش اصلی کمک می‌کند.","Porsesh-e far'i be roshan shodan-e porsesh-e asli komak mikonad.","A sub-question helps clarify the main question.");
 N(1,"N3-01","پدر","pedar","father","پدر برای فرزندش کتاب خرید.","Pedar barāye farzandash ketāb kharid.","The father bought a book for his child.");
 N(1,"N3-01","مادر","mādar","mother","مادر داستانی برای کودک خواند.","Mādar dāstāni barāye kudak khānd.","The mother read a story to the child.");
 N(1,"N3-01","مدرسه","madrese","school","دانش‌آموزان صبح به مدرسه می‌روند.","Dānesh-āmuzān sobh be madrese miravand.","Students go to school in the morning.");
 N(1,"N3-01","وجود","vojud","existence; presence","وجود منبع معتبر به تحقیق اعتبار می‌دهد.","Vojud-e manba'-e mo'tabar be tahqiq e'tebār midahad.","Having a reliable source gives research credibility.");
 N(1,"N3-01","گاهی","gāhi","sometimes; occasionally","گاهی یک مثال ساده موضوع را روشن می‌کند.","Gāhi yek mesāl-e sāde mozoo rā roshan mikonad.","Sometimes a simple example clarifies the topic.");
 V(1,"N3-04","نداشتن","nadāshtan","not to have; to lack","نداشتنِ برنامه باعث اتلاف وقت می‌شود.","Nadāshtan-e barnāme bā'es-e etlāf-e vaqt mishavad.","Not having a plan causes wasted time.","نداشتن","نداشته باش","نداشتنِ اطلاعات کافی تصمیم‌گیری را دشوار می‌کند.","Nadāshtan-e etelā'āt-e kāfi tasmim-giri rā doshvār mikonad.","Lacking sufficient information makes decision-making difficult.","چنین نگرشی نداشته باش.","Chenin negarshi nadāshte bāsh.","Do not have such an attitude.");
 V(1,"SH3-01","آمدن","āmadan","to come; to arrive","آمدنِ به‌موقع به کلاس نشانهٔ نظم است.","Āmadan-e be-moghe' be kelās neshāne-ye nazm ast.","Arriving to class on time is a sign of discipline.","آمدن","بیا","آمدن به جلسه با آمادگی بهتر است.","Āmadan be jalase bā āmādegi behtar ast.","It is better to come to the session prepared.","به موقع بیا.","Be moghe' biyā.","Come on time.");
 V(1,"SH3-01","شناختن","shenākhtan","to know; to recognise","شناختنِ نیازهای دیگران به همدلی کمک می‌کند.","Shenākhtan-e niyāzhā-ye digarān be hamdeli komak mikonad.","Recognising others' needs helps empathy.","شناختن","بشناس","شناختنِ تفاوت‌ها به گفت‌وگوی بهتر کمک می‌کند.","Shenākhtan-e tafāvothā be goft-o-gu-ye behtar komak mikonad.","Recognising differences helps better dialogue.","خود و توانایی‌های خود را بشناس.","Khod va tavānāyi-hā-ye khod rā beshnās.","Know yourself and your abilities.");
 V(1,"SH3-01","گذاشتن","gozāshtan","to put; to place; to leave","گذاشتنِ وسایل در جای مناسب نظم را بیشتر می‌کند.","Gozāshtan-e vasāyel dar jā-ye monāseb nazm rā bishtar mikonad.","Putting things in the right place improves order.","گذاشتن","بگذار","گذاشتنِ کتاب روی میز به یادآوری آن کمک می‌کند.","Gozāshtan-e ketāb ru-ye miz be yādāvari-ye ān komak mikonad.","Putting the book on the desk helps you remember it.","کتاب را روی میز بگذار.","Ketāb rā ru-ye miz bogozār.","Put the book on the desk.");
 V(1,"SH3-01","ساختن","sākhtan","to build; to make","ساختنِ عادت خوب به تکرار نیاز دارد.","Sākhtan-e ādat-e khub be tekrār niyāz dārad.","Building a good habit requires repetition.","ساختن","بساز","ساختنِ جمله با واژه‌های تازه تمرین خوبی است.","Sākhtan-e jomle bā vāzhehā-ye tāze tamrin-e khubi ast.","Making sentences with new words is good practice.","با این واژه یک جمله بساز.","Bā in vāzhe yek jomle besāz.","Make a sentence with this word.");
 V(1,"SH3-01","آوردن","āvardan","to bring; to carry","آوردنِ مثال مناسب فهم موضوع را آسان می‌کند.","Āvardan-e mesāl-e monāseb fahm-e mozoo rā āsān mikonad.","Giving a suitable example makes the topic easier to understand.","آوردن","بیاور","آوردنِ دلیل روشن به تقویت نظر کمک می‌کند.","Āvardan-e dalil-e roshan be taqviyat-e nazar komak mikonad.","Giving a clear reason strengthens an opinion.","کتاب را به کلاس بیاور.","Ketāb rā be kelās biyāvar.","Bring the book to class.");
 V(1,"N3-10","نمودن","nemudan","to show; to indicate (formal)","نمودنِ احترام در رفتار روزانه اهمیت دارد.","Nemudan-e ehterām dar raftār-e ruzāne ahammiyat dārad.","Showing respect in daily behaviour is important.","نمودن","بنما","نمودنِ توجه به سخن دیگران نشانهٔ ادب است.","Nemudan-e tavajjoh be sokhan-e digarān neshāne-ye adab ast.","Showing attention to others' words is a sign of courtesy.","لطفاً پاسخ را روشن‌تر بنما.","Lotfan pāsokh rā roshan-tar benamā.","Please make the answer clearer.");
 V(1,"N3-10","سنجیدن","sanjidan","to measure; to assess; to weigh","سنجیدنِ دلیل‌ها پیش از تصمیم‌گیری لازم است.","Sanjidan-e dalilhā pish az tasmim-giri lāzem ast.","Weighing the reasons before deciding is necessary.","سنجیدن","بسنج","سنجیدنِ پیامدها به انتخاب بهتر کمک می‌کند.","Sanjidan-e payāmad-hā be entekhāb-e behtar komak mikonad.","Assessing the consequences helps make a better choice.","پیش از انتخاب، گزینه‌ها را بسنج.","Pish az entekhāb gozinehā rā besanj.","Weigh the options before choosing.");
 const norm=x=>String(x||"").normalize("NFKC").replace(/[يى]/g,"ی").replace(/ك/g,"ک").replace(/[\u064B-\u065F\u0670\u0640]/g,"").replace(/[\u200c\s]+/g," ").trim().toLocaleLowerCase();
 const key=x=>[norm(x.fa),norm(x.tr),norm(x.en)].join("|");
 const byKey=new Map((window.TERM3_DATA||[]).map(x=>[key(x),x]));
 const additions=[];
 for(const x of rows){
  const k=key(x),prior=byKey.get(k);
  if(prior){
   prior.sources=Array.from(new Set([...(prior.sources||[prior.source]).filter(Boolean),x.source].filter(Boolean)));
   prior.units=Array.from(new Set([...(prior.units||[prior.unit]),x.unit]));
  }else{
   x.sources=[x.source];x.units=[x.unit];additions.push(x);byKey.set(k,x);
  }
 }
 window.TERM3_DATA=(window.TERM3_DATA||[]).concat(additions);
 window.TERM3_REVIEWED_SOURCE_ADDITIONS={sourceRows:rows.length,additions:additions.length,sourceIds:Array.from(new Set(rows.map(x=>x.source))).sort()};
})();